function o(t=new Date,n="America/Sao_Paulo"){return new Intl.DateTimeFormat("en-CA",{timeZone:n,year:"numeric",month:"2-digit",day:"2-digit"}).format(t)}function a(t){const[n,e,r]=t.slice(0,10).split("-").map(Number);return Math.floor(Date.UTC(n,e-1,r)/864e5)}function i(t,n){return a(t)-a(n)}function u(t,n,e=30){const r=i(t,n);return r<0?"expired":r<=e?"near":"valid"}export{i as d,u as e,o as t};
